  if (!Array.isArray(operations)) {
    throw new Error('patch must be an array');
  }

  // Check that document and all values are JSON-serializable
  try {
    JSON.stringify(document);
  } catch {
    throw new Error('document is not JSON data');
  }

  // Deep copy the document
  let result = deepCopy(document);

