    const op = operations[i];
    try {
      result = applyOperation(result, op);
    } catch (error) {
      if (error instanceof PointerError) {
        throw new PatchError(error.message, i, { cause: error });
      }
      throw new PatchError(error.message, i);
    }
  }

  return result;
